 const f=Math.max(20,Math.min(sampleRate*.499,band.frequency));
 const w=2*Math.PI*f/sampleRate,c=Math.cos(w),s=Math.sin(w);
 const A=10**(band.gain/40),alpha=s/(2*Math.max(.3,band.q));
 const base=[1+alpha,-2*c,1-alpha];
