 data.bands.forEach((b,i)=>{if(!b.known)return;const d=Math.hypot(eqX(b.frequency,g)-event.offsetX,eqY([0,5].includes(b.type)?0:b.gain,g)-event.offsetY);if(d<best){best=d;pick=i+1;}});
